"""Exact monetary amount parsing and formatting.

Amounts are handled as :class:`~decimal.Decimal` values with an exponent of
``-2`` (that is, exactly two decimal places).  No rounding ever happens: a
value whose fractional part is finer than one cent is rejected instead.
"""

import re
from decimal import Decimal

MAX_AMOUNT = Decimal("1000000.00")
MAX_AMOUNT_CENTS = 100_000_000

# A plain decimal string: optional sign, digits, and an optional fractional
# part.  Whitespace, exponents, and non-finite spellings are not part of the
# grammar.  Both "1." and ".5" are accepted as ordinary decimal literals.
_PLAIN_DECIMAL_RE = re.compile(
    r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)"
)


def parse_amount(value):
    """Parse *value* into an exact ``Decimal`` with exponent ``-2``.

    Accepted inputs are:

    * ``Decimal`` values,
    * ``int`` values (``bool`` is explicitly rejected),
    * plain decimal strings (no whitespace, no exponent, optionally signed).

    ``ValueError`` is raised for unsupported types, non-finite numbers, zero,
    negative values, values above ``1000000.00``, and values that are not
    exactly representable in cents.  Extra trailing zeros are accepted, but a
    nonzero fractional cent is never rounded away.
    """
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, int):
        amount = Decimal(value)
    elif isinstance(value, str):
        if _PLAIN_DECIMAL_RE.fullmatch(value) is None:
            raise ValueError(f"invalid amount string: {value!r}")
        amount = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not amount.is_finite():
        raise ValueError("amount must be finite")
    if amount.is_zero():
        raise ValueError("amount must be greater than zero")
    if amount < 0:
        raise ValueError("amount must not be negative")
    if amount > MAX_AMOUNT:
        raise ValueError("amount must not exceed 1000000.00")
    return _quantize_to_cents(amount)


def _quantize_to_cents(value):
    """Rescale an exactly representable value to exponent ``-2``.

    The conversion works directly on the Decimal tuple, so it neither rounds
    nor depends on the current decimal context.
    """
    sign, digits, exponent = value.as_tuple()
    if exponent >= -2:
        digits = digits + (0,) * (exponent + 2)
    else:
        extra = -exponent - 2
        if extra >= len(digits) or any(digits[len(digits) - extra:]):
            raise ValueError("amount must be exactly representable in cents")
        digits = digits[: len(digits) - extra]
    return Decimal((sign, digits, -2))


def _decimal_to_cents(value):
    """Convert an exponent ``-2`` Decimal into an integer number of cents."""
    sign, digits, exponent = value.as_tuple()
    if exponent != -2:
        raise ValueError("value is not expressed in cents")
    cents = 0
    for digit in digits:
        cents = cents * 10 + digit
    return -cents if sign else cents


def _cents_to_decimal(cents):
    """Build an exponent ``-2`` Decimal from an integer number of cents."""
    sign, magnitude = (1, -cents) if cents < 0 else (0, cents)
    digits = tuple(int(char) for char in str(magnitude))
    return Decimal((sign, digits, -2))


def format_amount(value):
    return format(value, ".2f")
